// Independent exhaustive oracle: repeated boolean relation composition, no queue.
function reach(successors, roots, depth=Infinity) {
 const seen=new Set(roots);let frontier=[...seen];
 for(let d=0;d<depth && frontier.length;d++) {const next=[];for(const v of frontier)for(const w of successors(v))if(!seen.has(w)){seen.add(w);next.push(w)}frontier=next;}
 return seen;
}
record('implicit-and-exhaustive',()=>{
 assert.deepEqual([...reach(n=>[n+1], [0], 4)],[0,1,2,3,4]);
 let cases=0;
 for(let mask=0;mask<512;mask++) {
  const edges=[];for(let s=0;s<3;s++)for(let t=0;t<3;t++)if(mask & (1<<(3*s+t)))edges.push([s,t]);
  for(let root=0;root<3;root++)for(let depth=0;depth<=3;depth++){
   let oracle=new Set([root]);for(let i=0;i<depth;i++){const next=new Set(oracle);for(const [s,t] of edges)if(oracle.has(s))next.add(t);oracle=next;}
   const got=reach(v=>edges.filter(e=>e[0]===v).map(e=>e[1]),[root],depth);
   assert.deepEqual([...got].sort(),[...oracle].sort());
   const v=createGraphView({nodes:[0,1,2].map(i=>({id:String(i)})),edges:edges.map(([s,t])=>({source:String(s),target:String(t),type:'r'})),nodeId:n=>n.id,maxDepth:3});
   const result=v.subgraph({rootIds:[String(root)],depth});assert.equal(result.ok,true);
   assert.deepEqual(result.value.nodes.map(n=>Number(n.id)).sort(),[...oracle].sort());cases++;
  }
 }
 return {simpleDirectedGraphsIncludingLoops:512,rootDepthCases:cases,implicitSuccessorOnly:true};
});

