interface InIncidence<V,E> { readonly inEdges: (vertex:V)=>Iterable<E>; readonly source:(edge:E)=>V }
declare const brand: unique symbol;
type UnitId=string & {readonly [brand]:'unit'};
type LessonId=string & {readonly [brand]:'lesson'};
declare const unit:UnitId,lesson:LessonId;
const implicit:Successors<number>={successors:n=>[n+1]};
const selected:Successors<UnitId>={successors:id=>[id]};
// @ts-expect-error: invariance induced by consumed+produced V; narrow input cannot serve all strings
const widened:Successors<string>=selected;
// @ts-expect-error: a different domain identity cannot be supplied
selected.successors(lesson);
const edge:GraphEdge<UnitId,'prerequisiteFor'>={source:unit,target:unit,type:'prerequisiteFor'};
const view=createGraphView({nodes:[{id:unit}],edges:[edge],nodeId:n=>n.id,maxDepth:3});
const expected:GraphView<{id:UnitId},UnitId,'prerequisiteFor'>=view;
// @ts-expect-error: no unwanted widening of edge-kind literals
const bad:GraphEdge<UnitId,'prerequisiteFor'>={...edge,type:'containsLesson'};
const r=expected.subgraph({rootIds:[unit],depth:0});
if(r.ok){const exact:'prerequisiteFor'|undefined=r.value.edges[0]?.type;}
// Demonstrate method bivariance on the actual interface; accepted but unsafe for root input.
const methodWidened:GraphView<{id:UnitId},string,'prerequisiteFor'>=view;
methodWidened.subgraph({rootIds:['not-a-branded-unit'],depth:0});
void implicit;

